function onAppendResponse(state, peerId, request, response) {
  // The peer replicator keeps at most one AppendEntries request in flight per peer.
  if (response.term > state.currentTerm) {
    state.stepDown(response.term);
    return;
  }

  if (!response.success) {
    state.nextIndex.set(
      peerId,
      Math.max(0, state.nextIndex.get(peerId) - 1)
    );
    return;
  }

  state.matchIndex.set(peerId, request.lastIndex);
  state.nextIndex.set(peerId, request.lastIndex + 1);
}

