function advanceCommitIndex(state, matchIndexByPeer) {
  // The map contains one valid match index for every follower.
  const replicatedThrough = [
    state.log.length - 1,
    ...Object.values(matchIndexByPeer)
  ].sort((a, b) => b - a);

  const quorumIndex = replicatedThrough[Math.floor(replicatedThrough.length / 2)];
  if (quorumIndex > state.commitIndex &&
      state.log[quorumIndex]?.term === state.currentTerm) {
    state.commitIndex = quorumIndex;
  }
  return state.commitIndex;
}

function applyAppendEntries(state, request) {
  if (request.term < state.currentTerm) {
    return { success: false, term: state.currentTerm };
  }
  state.currentTerm = request.term;
  state.leaderId = request.leaderId;

  if (request.prevLogIndex >= 0 &&
      state.log[request.prevLogIndex]?.term !== request.prevLogTerm) {
    return { success: false, term: state.currentTerm };
  }

  for (const entry of request.entries) {
    state.log[entry.index] = entry;
  }

  const matchedThrough = request.entries.length === 0
    ? request.prevLogIndex
    : request.entries[request.entries.length - 1].index;
  state.commitIndex = Math.max(
    state.commitIndex,
    Math.min(request.leaderCommit, matchedThrough)
  );
  return { success: true, term: state.currentTerm };
}

